"""
Restructure to put status (left) and customer + resource + actions
(right) side-by-side at the top, each half-width. Cancel button gets
the dark-red theme matching the legacy CANCEL-RED-DARK styling.

What changes:

  Layout before:
    [Header]
    [(banner)]
    [Status pipeline - full width]
    [Customer card - full width]
    [Assets ... | Rail (with resource card + action buttons)]

  Layout after:
    [Header]
    [(banner)]
    [Status pipeline | Customer + Resource + Actions]
    [Assets ... | Rail (without resource/actions)]

Specifics:
  - New .ma-top-row grid (50/50, stacks to single column under 900px)
  - Right tile combines: customer header (avatar/name/contact +
    View link), resource picker (Currently + Change-to + Save),
    and action buttons (Reschedule + Cancel, side-by-side)
  - Cancel button keeps the dark-red theme from G2 (still in effect)
  - Resource card removed from rail (moved to top tile)
  - Action buttons removed from rail (moved to top tile)
  - Standalone .ma-customer-card markup deleted (subsumed into top tile)
  - Avatar shrunk from 44px to 36px for the tighter top tile context

No backend changes. Data-attribute API preserved so existing
appointment-resource.js continues to bind correctly.

Standalone Python. Idempotent.
"""
